values (
  'en-cold-war-origins-trivia',
  'Cold War Origins Trivia: From Yalta to NATO',
  'Eight questions on how the Cold War began, from Yalta and the Iron Curtain to the Truman Doctrine, the Marshall Plan and the birth of NATO.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"Which February 1945 conference brought Roosevelt, Churchill and Stalin together to shape postwar Europe?","options":[{"id":"a","text":"Tehran","is_correct":false},{"id":"b","text":"Potsdam","is_correct":false},{"id":"c","text":"Yalta","is_correct":true},{"id":"d","text":"Geneva","is_correct":false}],"explanation":"The Yalta Conference in Crimea was the second wartime summit of the ''Big Three''."},{"id":"q2","question":"Who declared that an ''iron curtain'' had descended across Europe in a 1946 speech in Fulton, Missouri?","options":[{"id":"a","text":"Harry S. Truman","is_correct":false},{"id":"b","text":"Winston Churchill","is_correct":true},{"id":"c","text":"George C. Marshall","is_correct":false},{"id":"d","text":"Dwight D. Eisenhower","is_correct":false}],"explanation":"Churchill, then out of office, gave the speech on 5 March 1946 with Truman in the audience."},{"id":"q3","question":"The Truman Doctrine of 1947 first promised US aid to which two countries?","options":[{"id":"a","text":"France and Italy","is_correct":false},{"id":"b","text":"Greece and Turkey","is_correct":true},{"id":"c","text":"China and Korea","is_correct":false},{"id":"d","text":"Germany and Japan","is_correct":false}],"explanation":"Truman asked Congress for $400 million for Greece and Turkey to resist communist pressure."},{"id":"q4","question":"What was the official name of the Marshall Plan, announced in 1947?","options":[{"id":"a","text":"The European Recovery Program","is_correct":true},{"id":"b","text":"The Atlantic Charter","is_correct":false},{"id":"c","text":"The Point Four Program","is_correct":false},{"id":"d","text":"The New Deal for Europe","is_correct":false}],"explanation":"Officially the European Recovery Program, it sent over $12 billion to rebuild Western Europe from 1948."},{"id":"q5","question":"In which year was NATO founded by the Washington Treaty?","options":[{"id":"a","text":"1945","is_correct":false},{"id":"b","text":"1947","is_correct":false},{"id":"c","text":"1949","is_correct":true},{"id":"d","text":"1955","is_correct":false}],"explanation":"Twelve countries signed the North Atlantic Treaty on 4 April 1949."},{"id":"q6","question":"George F. Kennan''s strategy toward Soviet expansion became known as what?","options":[{"id":"a","text":"Rollback","is_correct":false},{"id":"b","text":"Containment","is_correct":true},{"id":"c","text":"Détente","is_correct":false},{"id":"d","text":"Brinkmanship","is_correct":false}],"explanation":"Kennan''s 1946 ''Long Telegram'' and 1947 ''X'' article framed the policy of containment."},{"id":"q7","question":"In which year did the Soviet Union test its first atomic bomb, ending the US monopoly?","options":[{"id":"a","text":"1945","is_correct":false},{"id":"b","text":"1949","is_correct":true},{"id":"c","text":"1953","is_correct":false},{"id":"d","text":"1957","is_correct":false}],"explanation":"The RDS-1 test on 29 August 1949 ended the four-year American nuclear monopoly."},{"id":"q8","question":"Which Soviet-led military alliance was created in 1955 as a counterweight to NATO?","options":[{"id":"a","text":"The Warsaw Pact","is_correct":true},{"id":"b","text":"Comecon","is_correct":false},{"id":"c","text":"The Cominform","is_correct":false},{"id":"d","text":"The Helsinki Group","is_correct":false}],"explanation":"The Warsaw Pact was signed on 14 May 1955, days after West Germany joined NATO."}]'::jsonb,
  null,
  array['cold war', 'trivia', 'history', '20th century', 'superpowers']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
