values (
  'es-trivia-origenes-de-la-guerra-fria',
  'Trivia de los orígenes de la Guerra Fría',
  'Ocho preguntas sobre el inicio de la Guerra Fría, de Yalta y el telón de acero a la Doctrina Truman, el Plan Marshall y el nacimiento de la OTAN.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"¿Qué conferencia de febrero de 1945 reunió a Roosevelt, Churchill y Stalin para definir la posguerra?","options":[{"id":"a","text":"Teherán","is_correct":false},{"id":"b","text":"Potsdam","is_correct":false},{"id":"c","text":"Yalta","is_correct":true},{"id":"d","text":"Ginebra","is_correct":false}],"explanation":"La Conferencia de Yalta, en Crimea, fue la segunda cumbre de guerra de los ''Tres Grandes''."},{"id":"q2","question":"¿Quién advirtió en 1946, en Fulton (Misuri), que un ''telón de acero'' había caído sobre Europa?","options":[{"id":"a","text":"Harry S. Truman","is_correct":false},{"id":"b","text":"Winston Churchill","is_correct":true},{"id":"c","text":"George C. Marshall","is_correct":false},{"id":"d","text":"Dwight D. Eisenhower","is_correct":false}],"explanation":"Churchill, ya fuera del cargo, pronunció el discurso el 5 de marzo de 1946 con Truman presente."},{"id":"q3","question":"La Doctrina Truman de 1947 prometió primero ayuda estadounidense a qué dos países?","options":[{"id":"a","text":"Francia e Italia","is_correct":false},{"id":"b","text":"Grecia y Turquía","is_correct":true},{"id":"c","text":"China y Corea","is_correct":false},{"id":"d","text":"Alemania y Japón","is_correct":false}],"explanation":"Truman pidió al Congreso 400 millones de dólares para Grecia y Turquía frente a la presión comunista."},{"id":"q4","question":"¿Cuál era el nombre oficial del Plan Marshall, anunciado en 1947?","options":[{"id":"a","text":"Programa de Recuperación Europea","is_correct":true},{"id":"b","text":"Carta del Atlántico","is_correct":false},{"id":"c","text":"Programa del Punto Cuarto","is_correct":false},{"id":"d","text":"Nuevo Trato para Europa","is_correct":false}],"explanation":"Oficialmente European Recovery Program: envió más de 12 000 millones de dólares para reconstruir Europa occidental desde 1948."},{"id":"q5","question":"¿En qué año se fundó la OTAN con el Tratado de Washington?","options":[{"id":"a","text":"1945","is_correct":false},{"id":"b","text":"1947","is_correct":false},{"id":"c","text":"1949","is_correct":true},{"id":"d","text":"1955","is_correct":false}],"explanation":"Doce países firmaron el Tratado del Atlántico Norte el 4 de abril de 1949."},{"id":"q6","question":"¿Cómo se conoció la estrategia de George F. Kennan frente a la expansión soviética?","options":[{"id":"a","text":"Retroceso","is_correct":false},{"id":"b","text":"Contención","is_correct":true},{"id":"c","text":"Distensión","is_correct":false},{"id":"d","text":"Al borde del abismo","is_correct":false}],"explanation":"El ''largo telegrama'' de 1946 y el artículo ''X'' de 1947 de Kennan definieron la política de contención."},{"id":"q7","question":"¿En qué año probó la URSS su primera bomba atómica, acabando con el monopolio estadounidense?","options":[{"id":"a","text":"1945","is_correct":false},{"id":"b","text":"1949","is_correct":true},{"id":"c","text":"1953","is_correct":false},{"id":"d","text":"1957","is_correct":false}],"explanation":"La prueba RDS-1 del 29 de agosto de 1949 cerró el monopolio nuclear estadounidense de cuatro años."},{"id":"q8","question":"¿Qué alianza militar liderada por la URSS se creó en 1955 como contrapeso a la OTAN?","options":[{"id":"a","text":"El Pacto de Varsovia","is_correct":true},{"id":"b","text":"El Comecon","is_correct":false},{"id":"c","text":"El Kominform","is_correct":false},{"id":"d","text":"El Grupo de Helsinki","is_correct":false}],"explanation":"El Pacto de Varsovia se firmó el 14 de mayo de 1955, días después de que Alemania Occidental entrara en la OTAN."}]'::jsonb,
  null,
  array['guerra fría', 'trivia', 'historia', 'siglo xx', 'otan']::text[],
  3,
  'published',
  false,
  false,
  now()
)
