insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-berlin-wall-trivia',
  'Berlin Wall Trivia: The Border That Divided a City',
  'Eight questions on the Berlin Wall, from its construction in 1961 and Checkpoint Charlie to Kennedy, Reagan and the night it fell in 1989.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"In which year did East Germany begin building the Berlin Wall?","options":[{"id":"a","text":"1949","is_correct":false},{"id":"b","text":"1953","is_correct":false},{"id":"c","text":"1961","is_correct":true},{"id":"d","text":"1968","is_correct":false}],"explanation":"Construction began in the night of 12–13 August 1961 to stop the flight of East Germans to the West."},{"id":"q2","question":"What was the official East German name for the Berlin Wall?","options":[{"id":"a","text":"The Anti-Fascist Protection Rampart","is_correct":true},{"id":"b","text":"The People''s Friendship Barrier","is_correct":false},{"id":"c","text":"The Western Defense Line","is_correct":false},{"id":"d","text":"The Socialist Unity Wall","is_correct":false}],"explanation":"East Germany called it the ''Antifaschistischer Schutzwall'', claiming it kept Western fascism out."},{"id":"q3","question":"Which crossing point between East and West Berlin became world famous?","options":[{"id":"a","text":"Checkpoint Alpha","is_correct":false},{"id":"b","text":"Checkpoint Bravo","is_correct":false},{"id":"c","text":"Checkpoint Charlie","is_correct":true},{"id":"d","text":"Checkpoint Delta","is_correct":false}],"explanation":"Checkpoint Charlie was the best-known crossing and the site of a US–Soviet tank standoff in October 1961."},{"id":"q4","question":"Who led East Germany when the Wall went up in 1961?","options":[{"id":"a","text":"Erich Honecker","is_correct":false},{"id":"b","text":"Walter Ulbricht","is_correct":true},{"id":"c","text":"Nikita Khrushchev","is_correct":false},{"id":"d","text":"Wilhelm Pieck","is_correct":false}],"explanation":"Ulbricht ordered the Wall; Erich Honecker, then security chief, oversaw its construction."},{"id":"q5","question":"Which US president declared ''Ich bin ein Berliner'' in West Berlin in 1963?","options":[{"id":"a","text":"Dwight D. Eisenhower","is_correct":false},{"id":"b","text":"John F. Kennedy","is_correct":true},{"id":"c","text":"Lyndon B. Johnson","is_correct":false},{"id":"d","text":"Ronald Reagan","is_correct":false}],"explanation":"Kennedy spoke at the Rathaus Schöneberg on 26 June 1963, nearly two years after the Wall rose."},{"id":"q6","question":"Who challenged ''Mr. Gorbachev, tear down this wall!'' at the Brandenburg Gate in 1987?","options":[{"id":"a","text":"George H. W. Bush","is_correct":false},{"id":"b","text":"Ronald Reagan","is_correct":true},{"id":"c","text":"Margaret Thatcher","is_correct":false},{"id":"d","text":"Helmut Kohl","is_correct":false}],"explanation":"Reagan delivered the line on 12 June 1987, two years before the Wall fell."},{"id":"q7","question":"On which date in 1989 did the Berlin Wall fall?","options":[{"id":"a","text":"3 October","is_correct":false},{"id":"b","text":"9 November","is_correct":true},{"id":"c","text":"17 November","is_correct":false},{"id":"d","text":"25 December","is_correct":false}],"explanation":"A botched press conference on 9 November 1989 sent crowds to the crossings, which opened that night."},{"id":"q8","question":"Who was president of the United States when the Berlin Wall fell?","options":[{"id":"a","text":"Ronald Reagan","is_correct":false},{"id":"b","text":"George H. W. Bush","is_correct":true},{"id":"c","text":"Bill Clinton","is_correct":false},{"id":"d","text":"Jimmy Carter","is_correct":false}],"explanation":"George H. W. Bush had taken office in January 1989; Germany reunified the following October."}]'::jsonb,
  null,
  array['berlin wall', 'cold war', 'trivia', 'history', 'germany']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
