values (
  'es-trivia-muro-de-berlin',
  'Trivia del muro de Berlín: la frontera que dividió una ciudad',
  'Ocho preguntas sobre el muro de Berlín, de su construcción en 1961 y el Checkpoint Charlie a Kennedy, Reagan y la noche de su caída en 1989.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"¿En qué año comenzó Alemania Oriental la construcción del muro de Berlín?","options":[{"id":"a","text":"1949","is_correct":false},{"id":"b","text":"1953","is_correct":false},{"id":"c","text":"1961","is_correct":true},{"id":"d","text":"1968","is_correct":false}],"explanation":"La construcción empezó la noche del 12 al 13 de agosto de 1961 para frenar la fuga de alemanes orientales."},{"id":"q2","question":"¿Cuál era el nombre oficial del muro en Alemania Oriental?","options":[{"id":"a","text":"Muralla Antifascista de Protección","is_correct":true},{"id":"b","text":"Barrera de la Amistad de los Pueblos","is_correct":false},{"id":"c","text":"Línea de Defensa Occidental","is_correct":false},{"id":"d","text":"Muro de la Unidad Socialista","is_correct":false}],"explanation":"La RDA lo llamó ''Antifaschistischer Schutzwall'', alegando que protegía del fascismo occidental."},{"id":"q3","question":"¿Qué punto de cruce entre Berlín Este y Oeste se hizo mundialmente famoso?","options":[{"id":"a","text":"Checkpoint Alpha","is_correct":false},{"id":"b","text":"Checkpoint Bravo","is_correct":false},{"id":"c","text":"Checkpoint Charlie","is_correct":true},{"id":"d","text":"Checkpoint Delta","is_correct":false}],"explanation":"Checkpoint Charlie fue el cruce más conocido y escenario de un cara a cara de tanques en octubre de 1961."},{"id":"q4","question":"¿Quién dirigía Alemania Oriental cuando se levantó el muro en 1961?","options":[{"id":"a","text":"Erich Honecker","is_correct":false},{"id":"b","text":"Walter Ulbricht","is_correct":true},{"id":"c","text":"Nikita Jruschov","is_correct":false},{"id":"d","text":"Wilhelm Pieck","is_correct":false}],"explanation":"Ulbricht ordenó el muro; Erich Honecker, entonces jefe de seguridad, supervisó su construcción."},{"id":"q5","question":"¿Qué presidente de Estados Unidos proclamó ''Ich bin ein Berliner'' en Berlín Oeste en 1963?","options":[{"id":"a","text":"Dwight D. Eisenhower","is_correct":false},{"id":"b","text":"John F. Kennedy","is_correct":true},{"id":"c","text":"Lyndon B. Johnson","is_correct":false},{"id":"d","text":"Ronald Reagan","is_correct":false}],"explanation":"Kennedy habló ante el Rathaus Schöneberg el 26 de junio de 1963, casi dos años después de levantado el muro."},{"id":"q6","question":"¿Quién lanzó el reto ''¡Señor Gorbachov, derribe este muro!'' ante la Puerta de Brandeburgo en 1987?","options":[{"id":"a","text":"George H. W. Bush","is_correct":false},{"id":"b","text":"Ronald Reagan","is_correct":true},{"id":"c","text":"Margaret Thatcher","is_correct":false},{"id":"d","text":"Helmut Kohl","is_correct":false}],"explanation":"Reagan pronunció la frase el 12 de junio de 1987, dos años antes de la caída del muro."},{"id":"q7","question":"¿En qué fecha de 1989 cayó el muro de Berlín?","options":[{"id":"a","text":"3 de octubre","is_correct":false},{"id":"b","text":"9 de noviembre","is_correct":true},{"id":"c","text":"17 de noviembre","is_correct":false},{"id":"d","text":"25 de diciembre","is_correct":false}],"explanation":"Una rueda de prensa confusa el 9 de noviembre de 1989 llevó a la multitud a los cruces, que se abrieron esa noche."},{"id":"q8","question":"¿Quién era presidente de Estados Unidos cuando cayó el muro?","options":[{"id":"a","text":"Ronald Reagan","is_correct":false},{"id":"b","text":"George H. W. Bush","is_correct":true},{"id":"c","text":"Bill Clinton","is_correct":false},{"id":"d","text":"Jimmy Carter","is_correct":false}],"explanation":"George H. W. Bush había asumido en enero de 1989; Alemania se reunificó en octubre del año siguiente."}]'::jsonb,
  null,
  array['muro de berlín', 'guerra fría', 'trivia', 'historia', 'alemania']::text[],
  3,
  'published',
  false,
  false,
  now()
)
