insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-space-race-trivia',
  'Space Race Trivia: From Sputnik to the Moon',
  'Eight questions on the US–Soviet space race, from Sputnik and Gagarin to the first spacewalk, Apollo 11 and the Apollo–Soyuz docking.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"What was the first artificial satellite, launched by the USSR in 1957?","options":[{"id":"a","text":"Explorer 1","is_correct":false},{"id":"b","text":"Sputnik 1","is_correct":true},{"id":"c","text":"Vostok 1","is_correct":false},{"id":"d","text":"Luna 2","is_correct":false}],"explanation":"Sputnik 1, a polished metal sphere, orbited Earth from 4 October 1957 and shocked the West."},{"id":"q2","question":"Who became the first human in space on 12 April 1961?","options":[{"id":"a","text":"Gherman Titov","is_correct":false},{"id":"b","text":"Alan Shepard","is_correct":false},{"id":"c","text":"Yuri Gagarin","is_correct":true},{"id":"d","text":"John Glenn","is_correct":false}],"explanation":"Gagarin orbited Earth once aboard Vostok 1 in a flight lasting 108 minutes."},{"id":"q3","question":"What was the name of the dog sent into orbit aboard Sputnik 2 in 1957?","options":[{"id":"a","text":"Laika","is_correct":true},{"id":"b","text":"Belka","is_correct":false},{"id":"c","text":"Strelka","is_correct":false},{"id":"d","text":"Zvezdochka","is_correct":false}],"explanation":"Laika was the first living creature to orbit Earth; Belka and Strelka flew and returned in 1960."},{"id":"q4","question":"Who was the first American in space, on a suborbital flight in May 1961?","options":[{"id":"a","text":"John Glenn","is_correct":false},{"id":"b","text":"Alan Shepard","is_correct":true},{"id":"c","text":"Gus Grissom","is_correct":false},{"id":"d","text":"Scott Carpenter","is_correct":false}],"explanation":"Shepard''s Freedom 7 flight on 5 May 1961 reached space but did not orbit; Glenn orbited in 1962."},{"id":"q5","question":"Who performed the first spacewalk in March 1965?","options":[{"id":"a","text":"Alexei Leonov","is_correct":true},{"id":"b","text":"Yuri Gagarin","is_correct":false},{"id":"c","text":"Ed White","is_correct":false},{"id":"d","text":"Valentina Tereshkova","is_correct":false}],"explanation":"Leonov spent about 12 minutes outside Voskhod 2; Ed White made the first US spacewalk months later."},{"id":"q6","question":"Which mission landed the first humans on the Moon in July 1969?","options":[{"id":"a","text":"Apollo 8","is_correct":false},{"id":"b","text":"Apollo 11","is_correct":true},{"id":"c","text":"Apollo 13","is_correct":false},{"id":"d","text":"Apollo 17","is_correct":false}],"explanation":"Armstrong and Aldrin landed on 20 July 1969 while Michael Collins orbited above."},{"id":"q7","question":"What was the name of Apollo 11''s lunar module?","options":[{"id":"a","text":"Columbia","is_correct":false},{"id":"b","text":"Eagle","is_correct":true},{"id":"c","text":"Intrepid","is_correct":false},{"id":"d","text":"Orion","is_correct":false}],"explanation":"Armstrong radioed ''The Eagle has landed'' after touchdown in the Sea of Tranquility."},{"id":"q8","question":"Which 1975 mission saw American and Soviet spacecraft dock in orbit?","options":[{"id":"a","text":"Soyuz 11","is_correct":false},{"id":"b","text":"Apollo–Soyuz Test Project","is_correct":true},{"id":"c","text":"Skylab 2","is_correct":false},{"id":"d","text":"Vostok 6","is_correct":false}],"explanation":"The Apollo–Soyuz docking in July 1975 was the first joint US–Soviet spaceflight and a symbol of détente."}]'::jsonb,
  null,
  array['space race', 'cold war', 'trivia', 'nasa', 'history']::text[],
  3,
  'published',
  false,
  false,
  now()
)
