values (
  'en-cuban-missile-crisis-trivia',
  'Cuban Missile Crisis Trivia: Thirteen Days in October',
  'Eight questions on the October 1962 Cuban Missile Crisis: the U-2 photographs, the naval quarantine, Kennedy and Khrushchev, and the deal.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"In which month and year did the Cuban Missile Crisis take place?","options":[{"id":"a","text":"April 1961","is_correct":false},{"id":"b","text":"October 1962","is_correct":true},{"id":"c","text":"August 1963","is_correct":false},{"id":"d","text":"November 1960","is_correct":false}],"explanation":"The crisis ran from 16 to 28 October 1962, after U-2 photos confirmed the missile sites."},{"id":"q2","question":"What did US U-2 spy planes photograph in Cuba in October 1962?","options":[{"id":"a","text":"Soviet troop ships","is_correct":false},{"id":"b","text":"Nuclear missile sites under construction","is_correct":true},{"id":"c","text":"A submarine base","is_correct":false},{"id":"d","text":"Radar stations","is_correct":false}],"explanation":"The photos showed SS-4 medium-range ballistic missiles able to reach much of the United States."},{"id":"q3","question":"What did President Kennedy call the US naval blockade of Cuba?","options":[{"id":"a","text":"An embargo","is_correct":false},{"id":"b","text":"A quarantine","is_correct":true},{"id":"c","text":"A siege","is_correct":false},{"id":"d","text":"An exclusion zone","is_correct":false}],"explanation":"Kennedy chose the word ''quarantine'' because a blockade is formally an act of war."},{"id":"q4","question":"How many days did the Cuban Missile Crisis last?","options":[{"id":"a","text":"7","is_correct":false},{"id":"b","text":"13","is_correct":true},{"id":"c","text":"21","is_correct":false},{"id":"d","text":"30","is_correct":false}],"explanation":"The ''thirteen days'' ran from Kennedy''s briefing on 16 October to Khrushchev''s announcement on 28 October."},{"id":"q5","question":"Who led the Soviet Union during the missile crisis?","options":[{"id":"a","text":"Leonid Brezhnev","is_correct":false},{"id":"b","text":"Nikita Khrushchev","is_correct":true},{"id":"c","text":"Alexei Kosygin","is_correct":false},{"id":"d","text":"Andrei Gromyko","is_correct":false}],"explanation":"Khrushchev had secretly ordered the missiles to Cuba and announced their withdrawal on 28 October."},{"id":"q6","question":"In a secret part of the deal, where did the US agree to remove its Jupiter missiles?","options":[{"id":"a","text":"Italy","is_correct":false},{"id":"b","text":"West Germany","is_correct":false},{"id":"c","text":"Turkey","is_correct":true},{"id":"d","text":"South Korea","is_correct":false}],"explanation":"The US pledged to quietly withdraw its Jupiter missiles from Turkey months later."},{"id":"q7","question":"Which Soviet submarine officer refused to authorize a nuclear torpedo launch during the crisis?","options":[{"id":"a","text":"Vasili Arkhipov","is_correct":true},{"id":"b","text":"Nikolai Shumkov","is_correct":false},{"id":"c","text":"Valentin Savitsky","is_correct":false},{"id":"d","text":"Alexander Marinesko","is_correct":false}],"explanation":"Arkhipov, aboard B-59 on 27 October, argued against launching, which required all three senior officers to agree."},{"id":"q8","question":"What was installed between Washington and Moscow in 1963 as a lesson of the crisis?","options":[{"id":"a","text":"A direct hotline","is_correct":true},{"id":"b","text":"A weekly summit call","is_correct":false},{"id":"c","text":"A shared radar network","is_correct":false},{"id":"d","text":"A joint naval patrol","is_correct":false}],"explanation":"The ''red telephone'' hotline let leaders write to each other directly instead of relying on slow telegrams."}]'::jsonb,
  null,
  array['cuban missile crisis', 'cold war', 'trivia', 'kennedy', 'history']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-crisis-de-los-misiles',
  'Trivia de la crisis de los misiles: trece días de octubre',
  'Ocho preguntas sobre la crisis de los misiles de octubre de 1962: las fotos del U-2, la cuarentena naval, Kennedy y Jruschov, y el acuerdo.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"¿En qué mes y año ocurrió la crisis de los misiles de Cuba?","options":[{"id":"a","text":"Abril de 1961","is_correct":false},{"id":"b","text":"Octubre de 1962","is_correct":true},{"id":"c","text":"Agosto de 1963","is_correct":false},{"id":"d","text":"Noviembre de 1960","is_correct":false}],"explanation":"La crisis duró del 16 al 28 de octubre de 1962, tras las fotos del U-2 que confirmaron las rampas."},{"id":"q2","question":"¿Qué fotografiaron los aviones espía U-2 de Estados Unidos en Cuba en octubre de 1962?","options":[{"id":"a","text":"Barcos de tropas soviéticos","is_correct":false},{"id":"b","text":"Rampas de misiles nucleares en construcción","is_correct":true},{"id":"c","text":"Una base de submarinos","is_correct":false},{"id":"d","text":"Estaciones de radar","is_correct":false}],"explanation":"Las fotos mostraban misiles balísticos SS-4 de alcance medio capaces de llegar a gran parte de Estados Unidos."},{"id":"q3","question":"¿Cómo llamó el presidente Kennedy al bloqueo naval de Cuba?","options":[{"id":"a","text":"Embargo","is_correct":false},{"id":"b","text":"Cuarentena","is_correct":true},{"id":"c","text":"Sitio","is_correct":false},{"id":"d","text":"Zona de exclusión","is_correct":false}],"explanation":"Kennedy eligió ''cuarentena'' porque un bloqueo es formalmente un acto de guerra."},{"id":"q4","question":"¿Cuántos días duró la crisis de los misiles?","options":[{"id":"a","text":"7","is_correct":false},{"id":"b","text":"13","is_correct":true},{"id":"c","text":"21","is_correct":false},{"id":"d","text":"30","is_correct":false}],"explanation":"Los ''trece días'' van del informe a Kennedy el 16 de octubre al anuncio de Jruschov el 28."},{"id":"q5","question":"¿Quién dirigía la Unión Soviética durante la crisis?","options":[{"id":"a","text":"Leonid Brézhnev","is_correct":false},{"id":"b","text":"Nikita Jruschov","is_correct":true},{"id":"c","text":"Alekséi Kosyguin","is_correct":false},{"id":"d","text":"Andréi Gromyko","is_correct":false}],"explanation":"Jruschov había ordenado en secreto enviar los misiles a Cuba y anunció su retiro el 28 de octubre."},{"id":"q6","question":"En una parte secreta del acuerdo, ¿de dónde se comprometió Estados Unidos a retirar sus misiles Júpiter?","options":[{"id":"a","text":"Italia","is_correct":false},{"id":"b","text":"Alemania Occidental","is_correct":false},{"id":"c","text":"Turquía","is_correct":true},{"id":"d","text":"Corea del Sur","is_correct":false}],"explanation":"Estados Unidos prometió retirar discretamente sus misiles Júpiter de Turquía meses después."},{"id":"q7","question":"¿Qué oficial soviético se negó a autorizar el lanzamiento de un torpedo nuclear durante la crisis?","options":[{"id":"a","text":"Vasili Arjipov","is_correct":true},{"id":"b","text":"Nikolái Shumkov","is_correct":false},{"id":"c","text":"Valentín Savitski","is_correct":false},{"id":"d","text":"Alexander Marinesko","is_correct":false}],"explanation":"Arjipov, a bordo del B-59 el 27 de octubre, se opuso al lanzamiento, que requería el acuerdo de tres oficiales."},{"id":"q8","question":"¿Qué se instaló entre Washington y Moscú en 1963 como lección de la crisis?","options":[{"id":"a","text":"Una línea directa o ''teléfono rojo''","is_correct":true},{"id":"b","text":"Una llamada semanal de cumbre","is_correct":false},{"id":"c","text":"Una red de radares compartida","is_correct":false},{"id":"d","text":"Una patrulla naval conjunta","is_correct":false}],"explanation":"La línea directa permitía a los líderes escribirse sin depender de telegramas lentos."}]'::jsonb,
  null,
  array['crisis de los misiles', 'guerra fría', 'trivia', 'cuba', 'historia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-fall-of-the-soviet-union-trivia',
  'Fall of the Soviet Union Trivia: 1985 to 1991',
  'Eight questions on the end of the USSR: glasnost and perestroika, Chernobyl, the fall of the Wall, the August coup and the last day of 1991.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"Which Soviet leader launched the reforms of glasnost and perestroika in the mid-1980s?","options":[{"id":"a","text":"Leonid Brezhnev","is_correct":false},{"id":"b","text":"Mikhail Gorbachev","is_correct":true},{"id":"c","text":"Boris Yeltsin","is_correct":false},{"id":"d","text":"Yuri Andropov","is_correct":false}],"explanation":"Gorbachev became general secretary in March 1985 and paired openness with economic restructuring."},{"id":"q2","question":"What did the word ''perestroika'' mean?","options":[{"id":"a","text":"Openness","is_correct":false},{"id":"b","text":"Restructuring","is_correct":true},{"id":"c","text":"Acceleration","is_correct":false},{"id":"d","text":"Transparency","is_correct":false}],"explanation":"Perestroika meant restructuring the economy; glasnost meant openness in public life."},{"id":"q3","question":"Which April 1986 disaster exposed failures the reforms could not hide?","options":[{"id":"a","text":"The Chernobyl nuclear accident","is_correct":true},{"id":"b","text":"The Kursk submarine sinking","is_correct":false},{"id":"c","text":"The Aral Sea drought","is_correct":false},{"id":"d","text":"The Armenian earthquake","is_correct":false}],"explanation":"The Chernobyl explosion and its attempted cover-up badly damaged trust in the Soviet system."},{"id":"q4","question":"Which symbol of the Cold War fell in November 1989?","options":[{"id":"a","text":"The Berlin Wall","is_correct":true},{"id":"b","text":"The Warsaw Pact","is_correct":false},{"id":"c","text":"The Iron Curtain monument","is_correct":false},{"id":"d","text":"Lenin''s Mausoleum","is_correct":false}],"explanation":"The Wall''s fall triggered the collapse of communist governments across Eastern Europe."},{"id":"q5","question":"Which Soviet republic declared independence first, in March 1990?","options":[{"id":"a","text":"Estonia","is_correct":false},{"id":"b","text":"Latvia","is_correct":false},{"id":"c","text":"Lithuania","is_correct":true},{"id":"d","text":"Georgia","is_correct":false}],"explanation":"Lithuania declared independence on 11 March 1990; Moscow refused to recognize it for over a year."},{"id":"q6","question":"What happened in August 1991 that fatally weakened Gorbachev?","options":[{"id":"a","text":"A failed coup by Communist hardliners","is_correct":true},{"id":"b","text":"A general strike by coal miners","is_correct":false},{"id":"c","text":"A NATO ultimatum","is_correct":false},{"id":"d","text":"A Western grain embargo","is_correct":false}],"explanation":"Hardliners detained Gorbachev for three days; Yeltsin''s defiance broke the coup and the party''s power."},{"id":"q7","question":"Which December 1991 accords declared the USSR dissolved and created the CIS?","options":[{"id":"a","text":"The Helsinki Final Act","is_correct":false},{"id":"b","text":"The Belovezha Accords","is_correct":true},{"id":"c","text":"The Treaty of Brest-Litovsk","is_correct":false},{"id":"d","text":"The Yalta Agreements","is_correct":false}],"explanation":"The leaders of Russia, Ukraine and Belarus signed the Belovezha Accords on 8 December 1991."},{"id":"q8","question":"On which date did Gorbachev resign and the Soviet flag come down over the Kremlin?","options":[{"id":"a","text":"8 December 1991","is_correct":false},{"id":"b","text":"25 December 1991","is_correct":true},{"id":"c","text":"31 December 1991","is_correct":false},{"id":"d","text":"1 January 1992","is_correct":false}],"explanation":"Gorbachev resigned on 25 December 1991; the USSR formally ceased to exist the next day."}]'::jsonb,
  null,
  array['soviet union', 'cold war', 'trivia', 'history', 'gorbachev']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'es-trivia-caida-de-la-urss',
  'Trivia de la caída de la URSS: de 1985 a 1991',
  'Ocho preguntas sobre el fin de la Unión Soviética: el glásnost y la perestroika, Chernóbil, la caída del muro, el golpe de agosto y 1991.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'history'),
  '[{"id":"q1","question":"¿Qué líder soviético lanzó las reformas del glásnost y la perestroika a mediados de los 80?","options":[{"id":"a","text":"Leonid Brézhnev","is_correct":false},{"id":"b","text":"Mijaíl Gorbachov","is_correct":true},{"id":"c","text":"Borís Yeltsin","is_correct":false},{"id":"d","text":"Yuri Andrópov","is_correct":false}],"explanation":"Gorbachov asumió como secretario general en marzo de 1985 y combinó apertura con reestructuración económica."},{"id":"q2","question":"¿Qué significaba la palabra ''perestroika''?","options":[{"id":"a","text":"Apertura","is_correct":false},{"id":"b","text":"Reestructuración","is_correct":true},{"id":"c","text":"Aceleración","is_correct":false},{"id":"d","text":"Transparencia","is_correct":false}],"explanation":"Perestroika significaba reestructurar la economía; glásnost, apertura en la vida pública."},{"id":"q3","question":"¿Qué desastre de abril de 1986 dejó al descubierto fallos que las reformas no pudieron ocultar?","options":[{"id":"a","text":"El accidente nuclear de Chernóbil","is_correct":true},{"id":"b","text":"El hundimiento del submarino Kursk","is_correct":false},{"id":"c","text":"La sequía del mar de Aral","is_correct":false},{"id":"d","text":"El terremoto de Armenia","is_correct":false}],"explanation":"La explosión de Chernóbil y su intento de encubrimiento dañaron gravemente la confianza en el sistema soviético."},{"id":"q4","question":"¿Qué símbolo de la Guerra Fría cayó en noviembre de 1989?","options":[{"id":"a","text":"El muro de Berlín","is_correct":true},{"id":"b","text":"El Pacto de Varsovia","is_correct":false},{"id":"c","text":"El monumento del telón de acero","is_correct":false},{"id":"d","text":"El mausoleo de Lenin","is_correct":false}],"explanation":"La caída del muro desencadenó el colapso de los gobiernos comunistas de Europa del Este."},{"id":"q5","question":"¿Qué república soviética declaró primero su independencia, en marzo de 1990?","options":[{"id":"a","text":"Estonia","is_correct":false},{"id":"b","text":"Letonia","is_correct":false},{"id":"c","text":"Lituania","is_correct":true},{"id":"d","text":"Georgia","is_correct":false}],"explanation":"Lituania declaró su independencia el 11 de marzo de 1990; Moscú tardó más de un año en reconocerla."},{"id":"q6","question":"¿Qué ocurrió en agosto de 1991 que debilitó fatalmente a Gorbachov?","options":[{"id":"a","text":"Un golpe de Estado fallido de la línea dura comunista","is_correct":true},{"id":"b","text":"Una huelga general de mineros","is_correct":false},{"id":"c","text":"Un ultimátum de la OTAN","is_correct":false},{"id":"d","text":"Un embargo occidental de grano","is_correct":false}],"explanation":"La línea dura retuvo a Gorbachov tres días; la resistencia de Yeltsin quebró el golpe y el poder del partido."},{"id":"q7","question":"¿Qué acuerdos de diciembre de 1991 declararon disuelta la URSS y crearon la CEI?","options":[{"id":"a","text":"El Acta Final de Helsinki","is_correct":false},{"id":"b","text":"Los Acuerdos de Belovézha","is_correct":true},{"id":"c","text":"El Tratado de Brest-Litovsk","is_correct":false},{"id":"d","text":"Los Acuerdos de Yalta","is_correct":false}],"explanation":"Los líderes de Rusia, Ucrania y Bielorrusia firmaron los Acuerdos de Belovézha el 8 de diciembre de 1991."},{"id":"q8","question":"¿En qué fecha renunció Gorbachov y se arrió la bandera soviética del Kremlin?","options":[{"id":"a","text":"8 de diciembre de 1991","is_correct":false},{"id":"b","text":"25 de diciembre de 1991","is_correct":true},{"id":"c","text":"31 de diciembre de 1991","is_correct":false},{"id":"d","text":"1 de enero de 1992","is_correct":false}],"explanation":"Gorbachov renunció el 25 de diciembre de 1991; la URSS dejó de existir formalmente al día siguiente."}]'::jsonb,
  null,
  array['unión soviética', 'guerra fría', 'trivia', 'historia', 'gorbachov']::text[],
  3,
  'published',
  false,
  false,
  now()
)
on conflict (slug) do nothing;

-- categories.quiz_count is maintained by the trigger on quizzes.

